+static struct otx2_nic *sw_fdb_netdev_to_nic(struct net_device *dev)
+{
+	struct device *parent = dev->dev.parent;
+
+	if (parent && parent->bus == &pci_bus_type) {
+		struct pci_dev *pdev = to_pci_dev(parent);
+
+		if (otx2_rep_dev(pdev)) {
